ST.xhtml:
// --- MOTOR A ---
fbPowerA(
    Axis:= SM_Drive_GenericDSP402,
    Enable:= GVL.bPowerA,
    bRegulatorOn:= GVL.bPowerA,
    bDriveStart:= GVL.bPowerA
);

fbMoveRelA(
    Axis:= SM_Drive_GenericDSP402,
    Execute:= GVL.bMoveA,
    Distance:= GVL.rDistanceA,     // Ingediende verplaatsing (bijv. 10 omwentelingen)
    Velocity:= GVL.rCentraleSnelheid, // Koppel aan de centrale snelheid
    Acceleration:= 1000,
    Deceleration:= 1000,
    Jerk:= 5000
);

// --- MOTOR B ---
fbPowerB(
    Axis:= SM_Drive_GenericDSP402_3,
    Enable:= GVL.bPowerB,
    bRegulatorOn:= GVL.bPowerB,
    bDriveStart:= GVL.bPowerB
);

fbMoveRelB(
    Axis:= SM_Drive_GenericDSP402_3,
    Execute:= GVL.bMoveB,
    Distance:= GVL.rDistanceB,     // Ingediende verplaatsing
    Velocity:= GVL.rCentraleSnelheid, // Koppel aan de centrale snelheid
    Acceleration:= 1000,
    Deceleration:= 1000,
    Jerk:= 5000
);

// Homing Motor A (Block Homing via -1 op CoE 6098)
fbHomeA(
    Axis:= SM_Drive_GenericDSP402,
    Execute:= GVL.bStartHomingA,
    Position:= 0.0, // Zet de positie op 0.0 zodra de rand geraakt is
    Done=> GVL.bHomingDoneA
);

// Homing Motor B
fbHomeB(
    Axis:= SM_Drive_GenericDSP402_3,
    Execute:= GVL.bStartHomingB,
    Position:= 0.0,
    Done=> GVL.bHomingDoneB
);

// Doorkoppelen van MainTask naar GVL
GVL.bPowerA    := bPowerA;
GVL.bMoveA     := bMoveA;
GVL.rSpeedA    := rSpeedA;
GVL.rDistanceA := rDistanceA;

GVL.bPowerB    := bPowerB;
GVL.bMoveB     := bMoveB;
GVL.rSpeedB    := rSpeedB;
GVL.rDistanceB := rDistanceB;

// 1. Motor aan- en uitzetten 
IF bknopaan THEN
	bPowerA := TRUE;
	bPowerB := TRUE;
	bknopaan:= FALSE;
END_IF

// 2. Reset de move-commando's aan het begin van de cyclus
GVL.bMoveA := FALSE;
GVL.bMoveB := FALSE;

// BEIDE MOTOREN
IF bStartlinksrechts THEN
	GVL.rDistanceA := 10.0;
	GVL.rDistanceB := -10.0;
	GVL.bMoveA 	   := TRUE;
	GVL.bMoveB 	   := TRUE;
	bstartlinksrechts := FALSE;
END_IF

IF bStartrechtslinks THEN
	GVL.rDistanceA := -10.0;
	GVL.rDistanceB := 10.0;
	GVL.bMoveA 	   := TRUE;
	GVL.bMoveB 	   := TRUE;
	bstartrechtslinks := FALSE;
END_IF

// --- BEIDE MOTOREN ---
IF bStartBeideRechts THEN
    GVL.rDistanceA    := 10.0;
    GVL.rDistanceB    := 10.0;
    GVL.bMoveA        := TRUE;
    GVL.bMoveB        := TRUE;
    bStartBeideRechts := FALSE;
END_IF;

IF bStartBeideLinks THEN
    GVL.rDistanceA   := -10.0;
    GVL.rDistanceB   := -10.0;
    GVL.bMoveA       := TRUE;
    GVL.bMoveB       := TRUE;
    bStartBeideLinks := FALSE;
END_IF;

// --- MOTOR A INDIVIDUEEL ---
IF bStartARechts THEN
    GVL.rDistanceA := 10.0;
    GVL.bMoveA     := TRUE;
    bStartARechts  := FALSE;
END_IF;

IF bStartALinks THEN
    GVL.rDistanceA := -10.0;
    GVL.bMoveA     := TRUE;
    bStartALinks   := FALSE;
END_IF;

// --- MOTOR B INDIVIDUEEL ---
IF bStartBRechts THEN
    GVL.rDistanceB := 10.0;
    GVL.bMoveB     := TRUE;
    bStartBRechts  := FALSE;
END_IF;

IF bStartBLinks THEN
    GVL.rDistanceB := -10.0;
    GVL.bMoveB     := TRUE;
    bStartBLinks   := FALSE;
END_IF;

// Pulssturing voor Kalibratie Motor B
IF bKnopHomingB THEN
    GVL.bStartHomingB := TRUE;
    bKnopHomingB       := FALSE; // Reset HMI knop
ELSE
    GVL.bStartHomingB := FALSE;
END_IF;

// 1. Reset-logica voor het opheffen van een geblokkeerde as/fout
fbResetA(Axis := SM_Drive_GenericDSP402, Execute := bResetKnop);
IF fbResetA.Done THEN
    bResetKnop := FALSE;
END_IF;

// 2. Pulssignaal voor Homing (stopt direct na 1 cyclus)
IF bKnopHomingA THEN
    GVL.bStartHomingA := TRUE;
    bKnopHomingA       := FALSE; // Reset HMI knop
ELSE
    GVL.bStartHomingA := FALSE; // Direct weer FALSE maken!
END_IF;
